/// Data contract class for <c>METAMEXMoveRejectedLinesService</c> class.
/// </summary>
[DataContractAttribute]
class METAMEXMoveRejectedLinesContract
{
    private METAMEXBatchId          batchId;
    private Name                    journalDescription;
    private DataAreaId              dataArea;
    private JournalId               prevJournalId;
    private int                     tasks;
    
}

